// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    uint constant TICKET_AMOUNT = 10;

    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address actor, uint64 t) public {
        // Admissible domain: a plain EOA player, distinct from the contract, the bank
        // (this test contract), and the zero address; arbitrary block timestamp.
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0);

        // Fund: player pays the ticket, contract holds Ether so fee/payout transfers succeed.
        vm.deal(actor, TICKET_AMOUNT);
        vm.deal(address(c), 1 ether);

        vm.warp(t);
        vm.prank(actor);
        c.play{value: TICKET_AMOUNT}();

        // Recompute the publicly-derived random bit for this play.
        uint256 bit = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, actor))) % 2;

        // General rule: the reference pays out and resets the pot exactly on bit 0,
        // and otherwise accumulates the ticket; the mutant wins on bit 1 instead,
        // so for every admissible input the pot ends up on the wrong side.
        assertTrue(bit == 0 ? c.pot() == 0 : c.pot() == TICKET_AMOUNT);
    }

    // The bank (msg.sender at deployment) must be able to accept the 1-wei fee transfer.
    receive() external payable {}
}
